def merge(intervals):
    # Rule 6: an interval with a > b raises ValueError, so no result is returned.
    # Rules 1 and 4: (a, b) is the half-open range [a, b), so an empty one
    # (a == b) covers nothing; it fails `a < b` and is never kept.
    # Rule 5: kept intervals are copied into the new list `kept`; the caller's
    # list is only iterated, never written to.
    kept = []
    for a, b in intervals:
        if a > b:
            raise ValueError(f"bad interval {(a, b)}")
        if a < b:
            kept.append((a, b))

    # Rule 5 (input order is arbitrary): sort the copy by start.
    kept.sort()

    # Rules 2 and 3: walking in start order, an interval whose start is at or
    # before the end of the last merged interval (a <= end, so the touching
    # case b1 == a2 is included) extends it; otherwise it starts a new
    # interval, which is disjoint from and after every earlier one.
    # Rule 7: each output interval is a new 2-tuple of the input's endpoints.
    merged = []
    for a, b in kept:
        if merged and a <= merged[-1][1]:
            start, end = merged[-1]
            merged[-1] = (start, max(end, b))
        else:
            merged.append((a, b))
    return merged
